+    let encoder_input = KimiRequest {
+        messages,
+        tools,
+        // The encoder renders only these choices; a named one stays a constraint.
+        tool_choice: kwargs
+            .get("tool_choice")
+            .filter(|choice| matches!(choice.as_str(), Some("required" | "none")))
+            .cloned(),
+        response_format,
+        args: HashMap::from([
