+    }
+    // SGLang renders every declared tool, whatever the tool_choice.
+    let prompt = KimiK3Formatter::new(false)
+        .render_prompt(&encoder_input)
+        .map_err(|error| error.to_string())?;
+    Ok((prompt, prefix))
+}
