+/// The request Dynamo's formatter sees, built the way SGLang calls its encoder.
+struct KimiRequest {
+    messages: Vec<Value>,
+    tools: Option<Value>,
+    tool_choice: Option<Value>,
+    response_format: Option<Value>,
+    args: HashMap<String, Value>,
+}
